import{_ as a,o as l,c as n,aw as o}from"./chunks/framework.DLufY-ao.js";const u=JSON.parse('{"title":"Reconciliation Algorithm","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/framework-react/react/reconciler/reconciliation.md","filePath":"wiki/dev-commit/framework-react/react/reconciler/reconciliation.md"}'),t={name:"wiki/dev-commit/framework-react/react/reconciler/reconciliation.md"};function e(p,s,c,r,i,y){return l(),n("div",null,[...s[0]||(s[0]=[o(`<h1 id="reconciliation-algorithm" tabindex="-1">Reconciliation Algorithm <a class="header-anchor" href="#reconciliation-algorithm" aria-label="Permalink to &quot;Reconciliation Algorithm&quot;">​</a></h1><h2 id="информация" tabindex="-1">Информация <a class="header-anchor" href="#информация" aria-label="Permalink to &quot;Информация&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Reconciliation Algorithm</p><ul><li><strong>Reconciliation Algorithm</strong> (алгоритм согласования) - алгоритм сравнения в React</li><li>Вычисление разницы между двумя Virtual DOM. Если компонент в дереве заменен на другой, то всё поддерево считается новым. Дальнейшее сравнение вглубь не происходит</li><li>Назначение: отличить одно дерево элементов от другого для определения частей, которые нужно будет заменить.</li><li><strong>Апдейт</strong> - изменение в данных, которые используются для отрисовки React приложения. Обычно это результат вызова метода setState. Это конечный результат отрисовки компонента.</li></ul></div><h3 id="эвристическии-алгоритм" tabindex="-1">Эвристический алгоритм <a class="header-anchor" href="#эвристическии-алгоритм" aria-label="Permalink to &quot;Эвристический алгоритм&quot;">​</a></h3><p>React реализует эвристический алгоритм O(n), который основывается на двух предположениях:</p><ol><li>Два элемента с разными типами произведут разные деревья</li><li>Разработчик может указать, какие дочерние элементы могут оставаться стабильными между разными рендерами с помощью пропа key</li></ol><h3 id="re-render" tabindex="-1">Re-render <a class="header-anchor" href="#re-render" aria-label="Permalink to &quot;Re-render&quot;">​</a></h3><ol><li><strong>Reconciler</strong> (Сверка). Работает как Call Stack. Вычисляет какие части дерева изменились</li><li><strong>Render</strong> (Переписовка): ReactDOM, React Native. Использует информацию из Reconciler, чтобы обновить ранее отрисованное дерево</li></ol><h3 id="время-обновления" tabindex="-1">Время обновления <a class="header-anchor" href="#время-обновления" aria-label="Permalink to &quot;Время обновления&quot;">​</a></h3><ul><li>Чтобы изменения происходили плавно, нужно обновлять анимацию 60 раз в секунду, т.е. каждые 16 ms (миллисекунд).</li></ul><blockquote><p>1 секунда = 1000 миллисекунд</p></blockquote><blockquote><p>1000 миллисекунд / 60 = 16 миллисекунд</p></blockquote><h2 id="алгоритм-сравнения" tabindex="-1">Алгоритм сравнения <a class="header-anchor" href="#алгоритм-сравнения" aria-label="Permalink to &quot;Алгоритм сравнения&quot;">​</a></h2><ul><li>При сравнении двух деревьев первым делом React сравнивает два корневых элемента. Поведение различается в зависимости от типов корневых элементов</li></ul><h3 id="_1-dom-элементы-различных-типов-div-и-span" tabindex="-1">1. DOM-элементы различных типов <code>&lt;div&gt;</code> и <code>&lt;span&gt;</code> <a class="header-anchor" href="#_1-dom-элементы-различных-типов-div-и-span" aria-label="Permalink to &quot;1. DOM-элементы различных типов \`&lt;div&gt;\` и \`&lt;span&gt;\`&quot;">​</a></h3><ul><li>Всякий раз, когда корневые элементы имеют различные типы, React уничтожает старое дерево и строит новое с нуля. Переходы от &lt;a&gt; к &lt;img&gt;, или от &lt;Article&gt; к &lt;Comment&gt;, или от &lt;Button&gt; к &lt;div&gt; приведут к полному перестроению</li><li>При уничтожении дерева старые DOM-узлы удаляются. Экземпляры компонента получают componentWillUnmount(). При построении нового дерева, новые DOM-узлы вставляются в DOM. Экземпляры компонента получают componentWillMount(), а затем componentDidMount(). Любое состояние, связанное со старым деревом, теряется</li><li>Любые компоненты, лежащие ниже корневого, также размонтируются, а их состояние уничтожится. Например, это произойдёт при таком сравнении: При этом старый Counter уничтожится, а новый — смонтируется</li></ul><h4 id="было" tabindex="-1">Было <a class="header-anchor" href="#было" aria-label="Permalink to &quot;Было&quot;">​</a></h4><div class="language-jsx"><button title="Copy Code" class="copy"></button><span class="lang">jsx</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#383A42;">&lt;</span><span style="color:#E45649;">div</span><span style="color:#383A42;">&gt;</span></span>
<span class="line"><span style="color:#383A42;">  &lt;</span><span style="color:#C18401;">Counter</span><span style="color:#383A42;"> /&gt;</span></span>
<span class="line"><span style="color:#383A42;">&lt;/</span><span style="color:#E45649;">div</span><span style="color:#383A42;">&gt;</span></span></code></pre></div><h4 id="стало" tabindex="-1">Стало <a class="header-anchor" href="#стало" aria-label="Permalink to &quot;Стало&quot;">​</a></h4><div class="language-jsx"><button title="Copy Code" class="copy"></button><span class="lang">jsx</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#383A42;">&lt;</span><span style="color:#E45649;">span</span><span style="color:#383A42;">&gt;</span></span>
<span class="line"><span style="color:#383A42;">  &lt;</span><span style="color:#C18401;">Counter</span><span style="color:#383A42;"> /&gt;</span></span>
<span class="line"><span style="color:#383A42;">&lt;/</span><span style="color:#E45649;">span</span><span style="color:#383A42;">&gt;</span></span></code></pre></div><h3 id="_2-dom-элементы-одного-типа-но-разных-атрибутов-div-classname-before-и-span-classname-after" tabindex="-1"><code>2. DOM-элементы одного типа, но разных атрибутов&lt;div className=&quot;before&quot;&gt;и&lt;span className=&quot;after&quot;&gt;</code> <a class="header-anchor" href="#_2-dom-элементы-одного-типа-но-разных-атрибутов-div-classname-before-и-span-classname-after" aria-label="Permalink to &quot;\`2. DOM-элементы одного типа, но разных атрибутов&lt;div className=&quot;before&quot;&gt;и&lt;span className=&quot;after&quot;&gt;\`&quot;">​</a></h3><ul><li>При сравнении двух React DOM-элементов одного типа, React смотрит на атрибуты обоих, сохраняет лежащий в основе этих элементов DOM-узел и обновляет только изменённые атрибуты</li><li>После обработки DOM-узла React рекурсивно проходится по дочерним элементам</li></ul><hr><ul><li>Сравнивая эти элементы, React знает, что нужно модифицировать только className у лежащего в основе DOM-узла</li></ul><div class="language-jsx"><button title="Copy Code" class="copy"></button><span class="lang">jsx</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#383A42;">&lt;</span><span style="color:#E45649;">div</span><span style="color:#986801;"> className</span><span style="color:#383A42;">=</span><span style="color:#50A14F;">&quot;before&quot;</span><span style="color:#986801;"> title</span><span style="color:#383A42;">=</span><span style="color:#50A14F;">&quot;stuff&quot;</span><span style="color:#383A42;"> /&gt;</span></span>
<span class="line"><span style="color:#383A42;">&lt;</span><span style="color:#E45649;">div</span><span style="color:#986801;"> className</span><span style="color:#383A42;">=</span><span style="color:#50A14F;">&quot;after&quot;</span><span style="color:#986801;"> title</span><span style="color:#383A42;">=</span><span style="color:#50A14F;">&quot;stuff&quot;</span><span style="color:#383A42;"> /&gt;</span></span></code></pre></div><hr><ul><li>Обновляя style, React знает, что нужно обновлять только изменившиеся свойства</li><li>При конвертации между этими элементами, React знает, что нужно модифицировать только стиль color, а fontWeight сохранить</li></ul><div class="language-jsx"><button title="Copy Code" class="copy"></button><span class="lang">jsx</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#383A42;">&lt;</span><span style="color:#E45649;">div</span><span style="color:#986801;"> style</span><span style="color:#383A42;">={ {</span><span style="color:#E45649;">color</span><span style="color:#0184BC;">:</span><span style="color:#50A14F;"> &#39;red&#39;</span><span style="color:#383A42;">, </span><span style="color:#E45649;">fontWeight</span><span style="color:#0184BC;">:</span><span style="color:#50A14F;"> &#39;bold&#39;</span><span style="color:#383A42;">} } /&gt;</span></span>
<span class="line"><span style="color:#383A42;">&lt;</span><span style="color:#E45649;">div</span><span style="color:#986801;"> style</span><span style="color:#383A42;">={ {</span><span style="color:#E45649;">color</span><span style="color:#0184BC;">:</span><span style="color:#50A14F;"> &#39;green&#39;</span><span style="color:#383A42;">, </span><span style="color:#E45649;">fontWeight</span><span style="color:#0184BC;">:</span><span style="color:#50A14F;"> &#39;bold&#39;</span><span style="color:#383A42;">} } /&gt;</span></span></code></pre></div><h3 id="_3-компоненты-одного-типа-app-и-app" tabindex="-1"><code>3. Компоненты одного типа&lt;App&gt;и&lt;App&gt;</code> <a class="header-anchor" href="#_3-компоненты-одного-типа-app-и-app" aria-label="Permalink to &quot;\`3. Компоненты одного типа&lt;App&gt;и&lt;App&gt;\`&quot;">​</a></h3><ul><li>Когда компонент обновляется, его экземпляр остаётся прежним, поэтому его состояние сохраняется между рендерами. React обновляет пропсы базового экземпляра компонента для соответствия новому элементу и вызывает componentWillUpdate() на базовом экземпляре</li><li>Далее вызывается метод render() и алгоритм сравнения рекурсивно обходит предыдущий и новый результаты</li></ul><h2 id="рекурсия-по-дочерним-элементам-и-ключи" tabindex="-1">Рекурсия по дочерним элементам и ключи <a class="header-anchor" href="#рекурсия-по-дочерним-элементам-и-ключи" aria-label="Permalink to &quot;Рекурсия по дочерним элементам и ключи&quot;">​</a></h2><h3 id="рекурсия-по-дочерним-элементам" tabindex="-1">Рекурсия по дочерним элементам <a class="header-anchor" href="#рекурсия-по-дочерним-элементам" aria-label="Permalink to &quot;Рекурсия по дочерним элементам&quot;">​</a></h3><ul><li>По умолчанию при рекурсивном обходе дочерних элементов DOM-узла React проходит по обоим спискам потомков одновременно и создаёт мутацию, когда находит отличие</li></ul><hr><ul><li>При добавлении элемента в конец дочерних элементов, преобразование между этими деревьями работает отлично</li><li>React сравнит два дерева &lt;li&gt;первый&lt;/li&gt;, сравнит два дерева &lt;li&gt;второй&lt;/li&gt;, а затем вставит дерево &lt;li&gt;третий&lt;/li&gt;</li></ul><h4 id="было-1" tabindex="-1">Было <a class="header-anchor" href="#было-1" aria-label="Permalink to &quot;Было&quot;">​</a></h4><div class="language-jsx"><button title="Copy Code" class="copy"></button><span class="lang">jsx</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#383A42;">&lt;</span><span style="color:#E45649;">ul</span><span style="color:#383A42;">&gt;</span></span>
<span class="line"><span style="color:#383A42;">  &lt;</span><span style="color:#E45649;">li</span><span style="color:#383A42;">&gt;первый&lt;/</span><span style="color:#E45649;">li</span><span style="color:#383A42;">&gt;</span></span>
<span class="line"><span style="color:#383A42;">  &lt;</span><span style="color:#E45649;">li</span><span style="color:#383A42;">&gt;второй&lt;/</span><span style="color:#E45649;">li</span><span style="color:#383A42;">&gt;</span></span>
<span class="line"><span style="color:#383A42;">&lt;/</span><span style="color:#E45649;">ul</span><span style="color:#383A42;">&gt;</span></span></code></pre></div><h4 id="стало-1" tabindex="-1">Стало <a class="header-anchor" href="#стало-1" aria-label="Permalink to &quot;Стало&quot;">​</a></h4><div class="language-jsx"><button title="Copy Code" class="copy"></button><span class="lang">jsx</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#383A42;">&lt;</span><span style="color:#E45649;">ul</span><span style="color:#383A42;">&gt;</span></span>
<span class="line"><span style="color:#383A42;">  &lt;</span><span style="color:#E45649;">li</span><span style="color:#383A42;">&gt;первый&lt;/</span><span style="color:#E45649;">li</span><span style="color:#383A42;">&gt;</span></span>
<span class="line"><span style="color:#383A42;">  &lt;</span><span style="color:#E45649;">li</span><span style="color:#383A42;">&gt;второй&lt;/</span><span style="color:#E45649;">li</span><span style="color:#383A42;">&gt;</span></span>
<span class="line"><span style="color:#383A42;">  &lt;</span><span style="color:#E45649;">li</span><span style="color:#383A42;">&gt;третий&lt;/</span><span style="color:#E45649;">li</span><span style="color:#383A42;">&gt;</span></span>
<span class="line"><span style="color:#383A42;">&lt;/</span><span style="color:#E45649;">ul</span><span style="color:#383A42;">&gt;</span></span></code></pre></div><hr><ul><li>Преобразование между этими деревьями работает плохо</li><li>React будет мутировать каждого потомка, вместо того чтобы оставить &lt;li&gt;Санкт-Петербург&lt;/li&gt; и &lt;li&gt;Москва&lt;/li&gt; нетронутыми</li></ul><h4 id="было-2" tabindex="-1">Было <a class="header-anchor" href="#было-2" aria-label="Permalink to &quot;Было&quot;">​</a></h4><div class="language-jsx"><button title="Copy Code" class="copy"></button><span class="lang">jsx</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#383A42;">&lt;</span><span style="color:#E45649;">ul</span><span style="color:#383A42;">&gt;</span></span>
<span class="line"><span style="color:#383A42;">  &lt;</span><span style="color:#E45649;">li</span><span style="color:#383A42;">&gt;Санкт-Петербург&lt;/</span><span style="color:#E45649;">li</span><span style="color:#383A42;">&gt;</span></span>
<span class="line"><span style="color:#383A42;">  &lt;</span><span style="color:#E45649;">li</span><span style="color:#383A42;">&gt;Москва&lt;/</span><span style="color:#E45649;">li</span><span style="color:#383A42;">&gt;</span></span>
<span class="line"><span style="color:#383A42;">&lt;/</span><span style="color:#E45649;">ul</span><span style="color:#383A42;">&gt;</span></span></code></pre></div><h4 id="стало-2" tabindex="-1">Стало <a class="header-anchor" href="#стало-2" aria-label="Permalink to &quot;Стало&quot;">​</a></h4><div class="language-jsx"><button title="Copy Code" class="copy"></button><span class="lang">jsx</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#383A42;">&lt;</span><span style="color:#E45649;">ul</span><span style="color:#383A42;">&gt;</span></span>
<span class="line"><span style="color:#383A42;">  &lt;</span><span style="color:#E45649;">li</span><span style="color:#383A42;">&gt;Ростов-на-Дону&lt;/</span><span style="color:#E45649;">li</span><span style="color:#383A42;">&gt;</span></span>
<span class="line"><span style="color:#383A42;">  &lt;</span><span style="color:#E45649;">li</span><span style="color:#383A42;">&gt;Санкт-Петербург&lt;/</span><span style="color:#E45649;">li</span><span style="color:#383A42;">&gt;</span></span>
<span class="line"><span style="color:#383A42;">  &lt;</span><span style="color:#E45649;">li</span><span style="color:#383A42;">&gt;Москва&lt;/</span><span style="color:#E45649;">li</span><span style="color:#383A42;">&gt;</span></span>
<span class="line"><span style="color:#383A42;">&lt;/</span><span style="color:#E45649;">ul</span><span style="color:#383A42;">&gt;</span></span></code></pre></div><h3 id="ключи" tabindex="-1">Ключи <a class="header-anchor" href="#ключи" aria-label="Permalink to &quot;Ключи&quot;">​</a></h3><ul><li>Когда у дочерних элементов есть ключи key, React использует их, чтобы сопоставить потомков исходного дерева с потомками последующего дерева</li><li>Ключ должен быть уникальным только среди его соседей, а не глобально</li></ul><hr><ul><li>Если добавить key к неэффективному примеру выше, преобразование дерева станет эффективным</li><li>Теперь React знает, что элемент с ключом &#39;2014&#39; — новый, а элементы с ключами &#39;2015&#39; и &#39;2016&#39; только что переместились</li></ul><h4 id="было-3" tabindex="-1">Было <a class="header-anchor" href="#было-3" aria-label="Permalink to &quot;Было&quot;">​</a></h4><div class="language-jsx"><button title="Copy Code" class="copy"></button><span class="lang">jsx</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#383A42;">&lt;</span><span style="color:#E45649;">ul</span><span style="color:#383A42;">&gt;</span></span>
<span class="line"><span style="color:#383A42;">  &lt;</span><span style="color:#E45649;">li</span><span style="color:#986801;"> key</span><span style="color:#383A42;">=</span><span style="color:#50A14F;">&quot;2015&quot;</span><span style="color:#383A42;">&gt;Санкт-Петербург&lt;/</span><span style="color:#E45649;">li</span><span style="color:#383A42;">&gt;</span></span>
<span class="line"><span style="color:#383A42;">  &lt;</span><span style="color:#E45649;">li</span><span style="color:#986801;"> key</span><span style="color:#383A42;">=</span><span style="color:#50A14F;">&quot;2016&quot;</span><span style="color:#383A42;">&gt;Москва&lt;/</span><span style="color:#E45649;">li</span><span style="color:#383A42;">&gt;</span></span>
<span class="line"><span style="color:#383A42;">&lt;/</span><span style="color:#E45649;">ul</span><span style="color:#383A42;">&gt;</span></span></code></pre></div><h4 id="стало-3" tabindex="-1">Стало <a class="header-anchor" href="#стало-3" aria-label="Permalink to &quot;Стало&quot;">​</a></h4><div class="language-jsx"><button title="Copy Code" class="copy"></button><span class="lang">jsx</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#383A42;">&lt;</span><span style="color:#E45649;">ul</span><span style="color:#383A42;">&gt;</span></span>
<span class="line"><span style="color:#383A42;">  &lt;</span><span style="color:#E45649;">li</span><span style="color:#986801;"> key</span><span style="color:#383A42;">=</span><span style="color:#50A14F;">&quot;2014&quot;</span><span style="color:#383A42;">&gt;Ростов-на-Дону&lt;/</span><span style="color:#E45649;">li</span><span style="color:#383A42;">&gt;</span></span>
<span class="line"><span style="color:#383A42;">  &lt;</span><span style="color:#E45649;">li</span><span style="color:#986801;"> key</span><span style="color:#383A42;">=</span><span style="color:#50A14F;">&quot;2015&quot;</span><span style="color:#383A42;">&gt;Санкт-Петербург&lt;/</span><span style="color:#E45649;">li</span><span style="color:#383A42;">&gt;</span></span>
<span class="line"><span style="color:#383A42;">  &lt;</span><span style="color:#E45649;">li</span><span style="color:#986801;"> key</span><span style="color:#383A42;">=</span><span style="color:#50A14F;">&quot;2016&quot;</span><span style="color:#383A42;">&gt;Москва&lt;/</span><span style="color:#E45649;">li</span><span style="color:#383A42;">&gt;</span></span>
<span class="line"><span style="color:#383A42;">&lt;/</span><span style="color:#E45649;">ul</span><span style="color:#383A42;">&gt;</span></span></code></pre></div><h2 id="правила" tabindex="-1">Правила <a class="header-anchor" href="#правила" aria-label="Permalink to &quot;Правила&quot;">​</a></h2><ol><li>Алгоритм не будет пытаться сопоставить поддеревья компонентов разных типов. Если вы заметите за собой, что пытаетесь чередовать компоненты разных типов с очень схожим выводом, то желательно сделать их компонентами одного типа</li><li>Ключи должны быть стабильными, предсказуемыми и уникальными. Нестабильные ключи (например, произведённые с помощью Math.random()) вызовут необязательное пересоздание многих экземпляров компонента и DOM-узлов, что может вызывать ухудшение производительности и потерю состояния у дочерних компонентов</li></ol>`,55)])])}const h=a(t,[["render",e]]);export{u as __pageData,h as default};
